window.RP_SESSION={"id":"S-3108ce8d6c38","messages":[{"id":"RP-III-0039060","time":"2026-03-03T11:31:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"여느때와 같이 잔디밭의 누워있을 줄 알았던 마리우스는···. 지금 연병장에 자리합니다. 마치 하나의 광물로 이루어진 듯한 검. 그림자처럼 새까만 검은 볏짚을 향합니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039061","time":"2026-03-03T11:32:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039062","time":"2026-03-03T11:32:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 1 = 1\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-III-0039063","time":"2026-03-03T11:33:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"허나, 마리우스는 과거와는 다릅니다. 몇 십년, 아니. 정확히는 기억할 수 없는 세월동안 검을 놓고 살았습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039064","time":"2026-03-03T11:33:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"팅! 맑은 음을 내며 검은 손을 튕겨져 나갑니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039065","time":"2026-03-03T11:34:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"검은 이윽고 흙바닥에 충돌하며 조각조각 부서졌고.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039066","time":"2026-03-03T11:34:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"마리우스는 그것을 텅 빈 두 눈으로 바라볼 뿐이었습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039067","time":"2026-03-03T11:34:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039068","time":"2026-03-03T11:34:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 7 = 7\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0039069","time":"2026-03-03T11:35:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"조각난 검들을 바라보던 마리우스는. 여전히 텅빈 마음으로 다가갑니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039070","time":"2026-03-03T11:35:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039071","time":"2026-03-03T11:35:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 7 = 7\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0039072","time":"2026-03-03T11:36:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"발로 조각을 툭툭 차고는.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039073","time":"2026-03-03T11:36:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039074","time":"2026-03-03T11:36:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 10 = 10\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0039075","time":"2026-03-03T11:36:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"굴복하지 않겠다는 듯. 손을 내밉니다···.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039076","time":"2026-03-03T11:37:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"스르르, 오른손에 몰려오며 점점 맺히는 검은 연기.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039077","time":"2026-03-03T11:39:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"이윽고 그것은 검은 속내를 상징하듯 서서히 응어리지며. 소드로 바뀌었습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039078","time":"2026-03-03T11:39:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"다시금, 마리우스는 또 검을 잡고 볏짚을 내려칩니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039079","time":"2026-03-03T11:39:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039080","time":"2026-03-03T11:39:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"매칭되는 캐릭터 정보를 찾을 수 없습니다.","characters":[]},{"id":"RP-III-0039081","time":"2026-03-03T11:39:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039082","time":"2026-03-03T11:39:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'마리우스'의 힘 판정 :\n[9] + [1] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0039083","time":"2026-03-03T11:41:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"볏짚은 이윽고 통째로 잘려나가며. 원형의 밑동만이 남았습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039084","time":"2026-03-03T11:43:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"그대로 주저 앉아 하늘을 바라봅니다···. 누군가가 연병장에 올까요?","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039085","time":"2026-03-03T12:20:00+09:00","room":"RP III","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"어? 누가 있네\"","characters":["P-d8e7afee7c51"]},{"id":"RP-III-0039086","time":"2026-03-03T12:21:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"빤히 연병장에 누워 검을 내동댕이 치자, 검은 조각나며 검은 연기로 변해···. 사라졌습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039087","time":"2026-03-03T12:22:00+09:00","room":"RP III","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"우와, 검이 사라졌어\"","characters":["P-d8e7afee7c51"]},{"id":"RP-III-0039088","time":"2026-03-03T12:22:00+09:00","room":"RP III","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"신기한듯 사라진 검이 있는 자리를 쳐다봅니다","characters":["P-d8e7afee7c51"]},{"id":"RP-III-0039089","time":"2026-03-03T12:28:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"누구지? 잘 알아볼 수 없는 사람입니다. 길드에 이렇게 이상한 눈동자색을 가진 사람은 없을텐데요. 두 눈의 색이 서로 똑같지 않습니다···.","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039090","time":"2026-03-03T12:28:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"“ 누구십니까. ”","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039091","time":"2026-03-03T12:28:00+09:00","room":"RP III","name":"루체","profile":"루체","identity":"reviewed","type":"dialogue","body":"루체가 모르는 사람이겠거니..\n\n\"루체에요!\"","characters":["P-d8e7afee7c51"]},{"id":"RP-III-0039092","time":"2026-03-03T19:25:00+09:00","room":"RP III","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]},{"id":"RP-III-0039093","time":"2026-03-03T19:25:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
